/* --------------------------------------------------------------------------
   右侧模块 3A: 车辆监控 (可轮播车辆列表卡片，根据司机接到乘客时间实时更新在途行程)
   -------------------------------------------------------------------------- */
let currentVehPage = 0;
let vehCarouselTimer = null;

function getVehicleRosterCards(curDataset, curT, isAll) {
  const allDrivers = curDataset.drivers || [];
  // 车辆监控只展示在岗运营的13辆车辆（总车辆22辆，运营中13辆，空驶9辆）
  const drivers = allDrivers.filter(d => d.status !== '离线').slice(0, 13);
  const orders = curDataset.orders || [];
  const bats = [92, 88, 74, 82, 95, 68, 79, 85, 90, 83, 76, 88, 91, 65, 78, 84, 92, 86, 73, 89, 94, 71, 80, 87, 93, 77, 85, 82, 89, 76, 81, 87];

  const list = [];
  drivers.forEach((driverObj, i) => {
    const cid = driverObj.car;
    const carOrders = orders.filter(o => o.car === cid);

    // 寻找司机接到乘客时间到了当前时间的最新行程
    let activeTrip = null;
    if (isAll) {
      activeTrip = carOrders[carOrders.length - 1];
    } else {
      // 1. 优先找当前正在载客中的行程: pickupTime <= curT 且 curT < deliveredTime
      activeTrip = carOrders.find(o => o.pickupTime <= curT && curT < o.deliveredTime);
      // 2. 其次找已接到乘客的最近一单: pickupTime <= curT
      if (!activeTrip) {
        const past = carOrders.filter(o => o.pickupTime <= curT);
        if (past.length) activeTrip = past[past.length - 1];
      }
      // 3. 初始排班
      if (!activeTrip && carOrders.length) {
        activeTrip = carOrders[0];
      }
    }

    const fromStop = activeTrip ? activeTrip.from : '西角码头';
    const toStop = activeTrip ? activeTrip.to : '南湾运动公园';
    const paxStr = activeTrip ? `${activeTrip.pax}人` : '4人';
    const rawPickup = (activeTrip && activeTrip.pickupTime && activeTrip.pickupTime !== '00:00:00')
      ? activeTrip.pickupTime.slice(0, 5)
      : '08:30';

    list.push({
      id: cid,
      driver: driverObj.driver,
      from: fromStop,
      to: toStop,
      pax: paxStr,
      pickupTime: rawPickup,
      status: '在线'
    });
  });

  const pages = [];
  for (let i = 0; i < list.length; i += 4) {
    pages.push(list.slice(i, i + 4));
  }
  return pages;
}

function renderVehRosterInner() {
  const curDataset = getCurrentDataset();
  const dyn = getDynamicState();
  const carPages = getVehicleRosterCards(curDataset, dyn.curT, dyn.isAll);
  const totalPages = carPages.length || 8;
  if (currentVehPage >= totalPages) currentVehPage = 0;
  const pageCars = carPages[currentVehPage] || carPages[0];

  const carRows = pageCars.map(c => {
    return `
      <div class="veh-card-mini" data-bus="${c.id}" role="button" tabindex="0" title="点击定位车辆 ${c.id}">
        <div class="vcm-left">
          <div class="vcm-id-row">
            <span class="vcm-dot"></span>
            <strong class="vcm-id font-num">${c.id}</strong>
          </div>
          <span class="vcm-driver">司机 · ${c.driver}</span>
        </div>
        <div class="vcm-mid">
          <div class="vcm-stop"><i class="s-dot from"></i><span class="vcm-stop-tag">起</span><span class="vcm-stop-name" title="${c.from}">${c.from}</span></div>
          <div class="vcm-stop"><i class="s-dot to"></i><span class="vcm-stop-tag to">终</span><span class="vcm-stop-name" title="${c.to}">${c.to}</span></div>
        </div>
        <div class="vcm-right">
          <div class="vcm-pax-chip"><span class="font-num">${c.pax.replace(/\/7/, '')}</span></div>
          <div class="vcm-time-row" title="接到乘客时间: ${c.pickupTime}">
            <span class="vcm-time-lbl">接客</span>
            <span class="vcm-time-val font-num">${c.pickupTime}</span>
          </div>
        </div>
      </div>
    `;
  }).join('');

  const dots = Array.from({ length: totalPages }, (_, i) => `
    <button class="pager-dot ${i === currentVehPage ? 'active' : ''}" data-action="setVehPage" data-page="${i}" aria-label="第 ${i + 1} 页"></button>
  `).join('');

  return `
    <div class="veh-roster-list">${carRows}</div>
    <div class="veh-roster-pager">
      <span class="pager-num font-num">在岗车辆 <b>${currentVehPage * 4 + 1}–${Math.min(13, (currentVehPage + 1) * 4)}</b> / 共 13 辆</span>
      <div class="pager-dots">${dots}</div>
    </div>
  `;
}

function setVehCarouselPage(p) {
  currentVehPage = p;
  const el = document.getElementById('veh-roster-body');
  if (el) el.innerHTML = renderVehRosterInner();
}

function startVehCarousel() {
  if (vehCarouselTimer) clearInterval(vehCarouselTimer);
  vehCarouselTimer = setInterval(() => {
    const curDataset = getCurrentDataset();
    const dyn = getDynamicState();
    const carPages = getVehicleRosterCards(curDataset, dyn.curT, dyn.isAll);
    const totalPages = carPages.length || 4;
    currentVehPage = (currentVehPage + 1) % totalPages;
    const el = document.getElementById('veh-roster-body');
    if (el) el.innerHTML = renderVehRosterInner();
  }, 4500);
}

