/* --------------------------------------------------------------------------
   右侧模块 3B: 事件监控 (按精确时间点动态触发新增，时间点前不展示)
   -------------------------------------------------------------------------- */
function incidentMonitorPanel(handled = new Set()) {
  const dyn = getDynamicState();
  const active = dyn.activeIncidents;
  const totalCount = active.length;

  if (totalCount === 0) {
    const badge = `<span class="tag-badge">今日 0 起预警</span>`;
    return `<section class="panel panel-incidents">
      ${panelHeader('事件监控', badge)}
      <div class="inc-stats-row">
        <div class="inc-stat-box err">
          <strong class="font-num">0</strong>
          <small>异常</small>
        </div>
        <div class="inc-stat-box warn">
          <strong class="font-num">0</strong>
          <small>预警</small>
        </div>
        <div class="inc-stat-box ok">
          <strong class="font-num">0</strong>
          <small>已处理</small>
        </div>
      </div>
      <div class="incident-empty">
        <div class="ie-text">暂无实时异常预警</div>
        <span class="ie-sub">当前时段全岛交通运转顺畅，系统持续监控中</span>
      </div>
    </section>`;
  }

  const handledCount = active.filter(i => handled.has(i.id) || i.status === '已处理').length;
  const unhandledWarn = active.filter(i => (i.type === 'warn' || !i.type) && !handled.has(i.id) && i.status !== '已处理').length;
  const unhandledErr = active.filter(i => i.type === 'err' && !handled.has(i.id) && i.status !== '已处理').length;

  const badge = `<span class="tag-badge">今日 ${totalCount} 起 · 待处理 ${unhandledWarn + unhandledErr} 条</span>`;

  const sortedActive = [...active].sort((a, b) => {
    const aHandled = handled.has(a.id) || a.status === '已处理' ? 1 : 0;
    const bHandled = handled.has(b.id) || b.status === '已处理' ? 1 : 0;
    if (aHandled !== bHandled) return aHandled - bHandled;
    return (b.exactTime || b.time || '').localeCompare(a.exactTime || a.time || '');
  });

  const cards = sortedActive.map(item => {
    const isHandled = handled.has(item.id) || item.status === '已处理';
    return `
      <div class="inc-v2-card ${item.type} ${isHandled ? 'is-handled' : ''}" data-action="openIncident" data-inc-id="${item.id}" role="button" tabindex="0" title="点击查看事件详情">
        <div class="inc-v2-top">
          <div class="inc-v2-meta">
            <span class="inc-v2-time font-num">${item.time}</span>
            <span class="inc-v2-badge ${item.type}">${item.tag || '预警'}</span>
            <span class="inc-v2-title">${item.title}</span>
          </div>
          <span class="inc-v2-status ${isHandled ? 'ok' : 'pending'}">${isHandled ? '已处理' : '未处理'}</span>
        </div>
        <div class="inc-v2-desc">${item.content}</div>
        <div class="inc-v2-footer">
          <div class="inc-v2-action-tag">处置建议: ${item.action}</div>
          <span class="inc-v2-btn-view">查看详情 &gt;</span>
        </div>
      </div>
    `;
  }).join('');

  return `<section class="panel panel-incidents">
    ${panelHeader('事件监控', badge)}
    <div class="inc-stats-row">
      <div class="inc-stat-box err">
        <strong class="font-num">${unhandledErr}</strong>
        <small>异常</small>
      </div>
      <div class="inc-stat-box warn">
        <strong class="font-num">${unhandledWarn}</strong>
        <small>预警</small>
      </div>
      <div class="inc-stat-box ok">
        <strong class="font-num">${handledCount}</strong>
        <small>已处理</small>
      </div>
    </div>
    <div class="incident-v2-list">${cards}</div>
  </section>`;
}

